#!/usr/bin/env python3
"""Compare actual PostgreSQL physics with fixtures generated by the Swift engine."""
import argparse
import json
import subprocess
from local_stack import NAMES

parser = argparse.ArgumentParser()
parser.add_argument("fixtures")
parser.add_argument("--container", default=NAMES["db"])
args = parser.parse_args()
with open(args.fixtures, encoding="utf-8") as stream:
    fixtures = json.load(stream)
literal = json.dumps(fixtures, ensure_ascii=False).replace("'", "''")
query = f"""
set statement_timeout = '30s';
select jsonb_build_object('name', f->>'name', 'actual', public.alkkagi_simulate(
 f->'stones', (f->>'stone_id')::integer,
 (f#>>'{{pull,x}}')::double precision, (f#>>'{{pull,y}}')::double precision))
from jsonb_array_elements('{literal}'::jsonb) f;
"""
result = subprocess.run(
    ["docker", "exec", "-i", args.container, "psql", "-X", "-q", "-A", "-t", "-v", "ON_ERROR_STOP=1", "-U", "postgres"],
    input=query, text=True, capture_output=True, check=True,
)
actual = {row["name"]: row["actual"] for row in map(json.loads, filter(str.strip, result.stdout.splitlines()))}
assert len(actual) == len(fixtures), (len(actual), len(fixtures))
maximum_error = 0.0
for fixture in fixtures:
    expected = fixture["expected"]
    observed = actual[fixture["name"]]
    assert observed["steps"] == expected["steps"], (fixture["name"], "steps", expected["steps"], observed["steps"])
    assert observed["result"] == expected["result"], (fixture["name"], "result")
    assert len(observed["stones"]) == len(expected["stones"])
    for a, b in zip(observed["stones"], expected["stones"]):
        for field in ("id", "owner", "isOut", "isPlaced"):
            assert a[field] == b[field], (fixture["name"], field)
        for field in ("position", "velocity"):
            for axis in ("x", "y"):
                delta = abs(a[field][axis] - b[field][axis])
                maximum_error = max(maximum_error, delta)
                assert delta < 1e-7, (fixture["name"], a["id"], field, axis, delta)
print(json.dumps({"passed": len(fixtures), "maximum_coordinate_error": maximum_error}))
